// Playwright CLI run-code callback. Use ONLY a disposable browser session with
// Vite running and an era-demo fixture generated by npm run demo:eras.
// Captures production frames at 24 fps; encode the JPEGs with ffmpeg afterward.
// prettier-ignore
async (page) => {
  const errors = [];
  page.on('pageerror', (error) => errors.push(error.message));
  await page.setViewportSize({ width: 1440, height: 900 });
  const profile = await page.evaluate(async () => {
    const profile = await (await fetch('/output/era-demo/contemporary-complete.json')).json();
    const { LEVEL_COUNT } = await import('/src/data/campaign.js');
    profile.records = Object.fromEntries(
      Array.from({ length: LEVEL_COUNT }, (_, i) => [i + 1, { score: 50000, stars: 3 }]),
    );
    profile.records[1].stars = 2;
    profile.town.nextRaidRun = 99999;
    profile.town.presentations = {};
    return profile;
  });
  await page.addInitScript((profile) => {
    if (sessionStorage.getItem('completion-video-fixture')) return;
    localStorage.setItem('crystal-cascade-profile-v3', JSON.stringify(profile));
    sessionStorage.setItem('completion-video-fixture', 'yes');
  }, profile);
  await page.reload();
  await page.waitForFunction(
    () => document.querySelector('.town-scene')?.__vueParentComponent?.setupState?.scene,
  );
  // Earn the last missing star through the production victory transaction.
  await page.evaluate(() => {
    const campaign = document
      .querySelector('#app')
      .__vue_app__.config.globalProperties.$pinia._s.get('campaign');
    campaign.recordVictory({ id: 1, score: 50000, target: 100, combo: 10 });
  });
  await page.getByRole('dialog', { name: 'Prospect Hollow · 100% complete' }).waitFor();
  await page.evaluate(() => {
    const scene = document.querySelector('.town-scene').__vueParentComponent.setupState.scene;
    const cinematic = document.querySelector('.town-presentation').__vueParentComponent;
    cancelAnimationFrame(cinematic.setupState.frame);
    scene.renderer.setAnimationLoop(null);
    scene.renderer.setPixelRatio(1);
    scene.resize();
    window.completionCapture = { scene, cinematic, start: scene.elapsed };
  });
  await page.mouse.move(5, 5);
  for (let frame = 0; frame < 456; frame++) {
    await page.evaluate(
      (time) => {
        const { scene, cinematic, start } = window.completionCapture;
        scene.elapsed = start + time;
        scene.actors.forEach((actor) => scene.animatePerson(actor, scene.elapsed));
        if (scene.waterMaterial) scene.waterMaterial.uniforms.time.value = scene.elapsed;
        cinematic.setupState.elapsed = time;
        cinematic.emit('frame', time);
      },
      Math.min(18, frame / 24),
    );
    await page.screenshot({
      path: `output/playwright/completion-fireworks-frames/${String(frame).padStart(5, '0')}.jpg`,
      type: 'jpeg',
      quality: 92,
    });
  }
  if (errors.length) throw Error(errors.join('\n'));
  return { frames: 456, fps: 24, duration: 19, errors };
}
